        "title": "El puesto que buscaba sombra",
        "summary": "Una dificultad del trabajo cotidiano obliga a distinguir qué debe cambiar y qué conviene mantener.",
        "paragraphs": [
          "Bruna extendía sus cintas tejidas por colores sobre un mostrador de madera, en el mercado de la ribera. Ataba los lazos allí mismo, sentada detrás, con una cesta de cintas pendientes a los pies. Algunas personas elegían un color y esperaban a que acabara el nudo. Otras miraban las bandejas mientras seguían su camino entre los puestos.",
          "Neri, un niño del valle que llevaba recados entre la plaza y el molino, se acercó con su amiga Isona. Mientras contaban una escena que habían visto junto al arroyo, Bruna levantó la mano hasta la frente. Había soltado un lazo a medio hacer. La sombra del nogal ya no alcanzaba su taburete y el sol le daba en los ojos cuando inclinaba la cabeza.",
          "Neri señaló un espacio bajo las ramas: moviendo el mostrador hasta allí, todo quedaría a la sombra. Bruna dejó la cinta sobre la mesa y miró hacia el paso. Una vecina avanzaba con un cesto a cada lado del cuerpo. El mostrador atravesado dejaría un hueco por el que tendría que girarse. Neri siguió con los ojos el recorrido de los cestos y bajó la mano.",
          "Isona rodeó el puesto. En un extremo de la mesa había una franja de sombra. «¿Te molesta el sol en las cintas o al hacer los nudos?», preguntó. Bruna le mostró el lazo inacabado: tenía que mirarlo de cerca para ajustar las dos partes. Isona acercó el taburete a aquella franja y esperó a que la vendedora probara el asiento.",
          "Bruna terminó el nudo sin entrecerrar los ojos. Entonces acercó la cesta de trabajo, pero dejó delante las bandejas de lazos acabados. Alguien que llegara por la plaza aún podría ver los colores. Neri recogió una cinta que había caído y pasó junto al puesto: la cesta estaba junto a las piernas de Bruna y el camino seguía despejado.",
          "La vecina de los dos cestos se detuvo para elegir un lazo rojo. Bruna se levantó, le acercó la bandeja y volvió después a su asiento. Neri e Isona salieron hacia el molino de Elna. Desde el borde de la plaza distinguieron el taburete bajo las hojas y la larga fila de cintas iluminadas sobre el mismo mostrador."
        ],
